```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut out: Vec<FeedItem> = Vec::with_capacity(items.len());

        for item in items {
            // Enrichment fetch, approved via http-client grant. The result is
            // not folded into the output: the node's contract is unchanged, so
            // the fetch is best-effort and its value is intentionally discarded.
            // `fetch` (not `get`) is used so a transport failure is a value, not
            // a trap, and one bad fetch cannot fail the whole call.
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                item.text
            );
            let _ = http_client::fetch(&url);

            // DropSeen: keep an item only if its id is not already recorded in
            // the 'seen' store. `id` is the parser's digest, safe as a key.
            // The read-only state handle has no `put`, so this run cannot alter
            // what the next run sees.
            if state_read::get(&item.id).is_none() {
                out.push(item);
            }
        }

        out
    }
}

export!(Node);
